#!/bin/bash
set -u
mkdir -p /tmp/vq-final
python3 - <<'PYEOF2'
import base64, os
BUNDLE = """PATCH:vq-001-motion-never-gates-content

PATCH:vq-002-hero-pill-on-dark

PATCH:vq-004-typographic-hero-treatment

PATCH:m-issue-2-fab-inflow-mobile

PATCH:m-issue-3-mobile-hero-call-cta

"""
name = None
os.makedirs("/tmp/vq-final", exist_ok=True)
for line in BUNDLE.split("\n"):
    line = line.strip()
    if line.startswith("PATCH:"):
        name = line[6:]
    elif line and name:
        open("/tmp/vq-final/" + name + ".patch", "wb").write(base64.b64decode(line))
        name = None
print("decoded:", sorted(os.listdir("/tmp/vq-final")))
PYEOF2
cd /home/nolan/projects/ping
for p in /tmp/vq-final/*.patch; do
  n=$(basename "$p" .patch)
  if git apply --check "$p" 2>/tmp/vq-err.txt; then
    echo "PASS(check): $n"
  else
    echo "FAIL(check): $n"
    cat /tmp/vq-err.txt
  fi
done
echo "=== repo status ==="
git status --porcelain | wc -l
git status --porcelain -- src/fyd/components/renderer.tsx src/fyd/components/object-rail.tsx src/fyd/components/__tests__/mobile-visibility.test.ts
